export type ClientInvoice = {
  id: string;
  organization_id: string;
  /**
   * Attachment UUID corresponding to that particular invoice.
   * <br>The attachment is generated **asynchronously**. While it is being generated this property is **omitted from the response** rather than returned as `null`, so treat an absent `attachment_id` as "not ready yet" and keep polling. After creating the invoice (by calling the [POST /v2/client_invoices](/api-reference/business-api/invoicing/client-invoices/create-a-client-invoice) endpoint) or finalizing it, wait ~10s and then call the [GET /v2/client_invoices/{id}](https://api-doc.qonto.com/docs/business-api/copd6wc7nwym8-show-client-invoice) endpoint until `attachment_id` is present.
   * <br>This property enables you to get the invoice file by using the [GET /v2/attachments/{id}](/api-reference/business-api/transactions-statements/attachments/retrieve-an-attachment) endpoint.
   * <br>The file is a PDF for invoices created on Qonto. Imported invoices keep their original file, which may also be a JPEG or a PNG, so read `file_content_type` from the attachment response instead of assuming `application/pdf`.
   */
  attachment_id?: string;
  number: string;
  /**
   * Purchase order data added by the invoice’s initiator.
   */
  purchase_order: string;
  status: "draft" | "unpaid" | "paid" | "canceled";
  /**
   * URL of the invoice public page, accessible without authentication for 180 days after issuance, provided the invoice has not been canceled.
   */
  invoice_url: string;
  /**
   * E-mail address of the invoice’s initiator.
   */
  contact_email: string;
  /**
   * The T&C data added by the invoice’s initiator.
   */
  terms_and_conditions: string;
  /**
   * Any discount for advance payment of the invoice. It is optional and is only for French organizations.
   */
  discount_conditions: string | null;
  /**
   * Late payment penalties applied in case of non-payment invoice.  It is optional and is only for French organizations.
   */
  late_payment_penalties: string | null;
  /**
   * The legal fixed compensation applied in case late payment of the invoice. It is optional and is only for French organizations.
   */
  legal_fixed_compensation: string | null;
  /**
   * The header text added by the credit note’s initiator.
   */
  header: string;
  /**
   * The footer text added by the credit note’s initiator.
   */
  footer: string;
  currency: string;
  /**
   * Global discount that was applied to the invoice.
   */
  discount?: {
    /**
     * Type of the discount applied.
     */
    type?: "percentage" | "absolute";
    /**
     * Rate or absolute amount that was discounted.
     */
    value?: string;
    /**
     * The calculated discount amount that was deducted from the invoice.
     */
    amount?: {
      value?: string;
      currency?: string;
    };
  };
  /**
   * Total amount that needs to be paid by the client.
   */
  total_amount: {
    value?: string;
    currency?: string;
  };
  /**
   * Total amount in cents that needs to be paid by the client.
   */
  total_amount_cents: number;
  /**
   * VAT amount that is applicable to the invoice.
   */
  vat_amount: {
    value?: string;
    currency?: string;
  };
  /**
   * VAT amount in cents that is applicable to the invoice.
   */
  vat_amount_cents: number;
  /**
   * Date the initiator mentioned that the invoice was created.
   */
  issue_date: string;
  /**
   * Payment’s deadline added by the initiator.
   */
  due_date: string;
  /**
   * Date the client is expected to pay the invoice.
   *
   * Omitted when the invoice has no expected date, or when the organization turned off expected dates in its invoicing settings in the Qonto app.
   *
   */
  expected_date?: {
    /**
     * Expected payment date. It stays in the past once the invoice is overdue.
     */
    date: string;
    /**
     * How the expected date was set:
     * - `client_average`: the due date plus the client's average payment delay.
     * - `manual`: set by a user.
     *
     */
    source: "client_average" | "manual";
    /**
     * The client's average payment delay in days. `0` means the client pays on time. Only returned when `source` is `client_average`.
     */
    client_average_delay_days?: number;
  };
  /**
   * Start date of the performance period mentioned by the initiator for the invoice contents.
   *
   * The performance period defines the date range during which the job or service was completed by the client. This field marks the beginning of that period and can be used together with `performance_end_date` to create a flexible date range instead of a single fixed date.
   *
   */
  performance_start_date: string | null;
  /**
   * End date of the performance period mentioned by the initiator for the invoice contents.
   *
   * This field defines the end of the performance date range, allowing the work or service to have been completed anytime between `performance_start_date` and `performance_end_date`. When used together with `performance_start_date`, it creates a flexible time window rather than specifying completion on a single specific date.
   *
   */
  performance_end_date: string | null;
  /**
   * Date the invoice was created. Note that this is a machine date.
   */
  created_at: string;
  /**
   * Date the invoice was transitioned from `Draft` to `Unpaid` status.
   */
  finalized_at: string | null;
  /**
   * Date on which the invoice was paid.
   */
  paid_at: string | null;
  /**
   * Amount paid for this invoice, expressed as a money object.
   *
   * **Note**: The `amount_paid` object is always returned. In the following cases, `amount_paid.value` is `'0.00'`:
   * - The invoice was manually marked as paid and is not linked to a transaction.
   * - The invoice is linked to a transaction that occurred before January 1, 2026.
   */
  amount_paid?: {
    value?: string;
    currency?: string;
  };
  stamp_duty_amount: string;
  items: DocumentItem[] | null;
  client: EmbeddedClient;
  payment_methods: {
    /**
     * Name of the beneficiary that will receive the invoice's payment.
     */
    beneficiary_name?: string;
    /**
     * Beneficiary’s International Bank Account Number.
     */
    bic?: string;
    /**
     * Beneficiary account's Bank Identifier.
     */
    iban?: string;
    /**
     * Invoice's payment method.
     */
    type?: "transfer";
  }[];
  /**
   * If any credit notes are linked to the invoice, this represents the id of those credit notes.
   */
  credit_notes_ids: string[];
  organization: EmbeddedInvoiceOrganization;
  /**
   * Only applicable to Italian organizations. Remains blank for French organizations.
   */
  einvoicing_status?:
    | "pending"
    | "submitted"
    | "declined"
    | "approved"
    | "not_delivered"
    | "submission_failed";
  welfare_fund?: {
    type?:
      | "TC01"
      | "TC02"
      | "TC03"
      | "TC04"
      | "TC05"
      | "TC06"
      | "TC07"
      | "TC08"
      | "TC09"
      | "TC10"
      | "TC11"
      | "TC12"
      | "TC13"
      | "TC14"
      | "TC15"
      | "TC16"
      | "TC17"
      | "TC18"
      | "TC19"
      | "TC20"
      | "TC21"
      | "TC22";
    rate?: string;
  };
  /**
   * - Only applicable for Italian organizations and Spanish freelancers.
   * - Object which relates to an amount of tax paid by the client, rather than the supplier, for specific cases.
   * - This amount is a percentage deducted from the total amount of the invoice after VAT application.
   * - The `rate` field specifies the percentage of tax and `amount` field specifies the total amount of the tax.
   */
  withholding_tax?: {
    reason?: "RF01" | "RF02" | "RF03" | "RF04" | "RF05" | "RF06";
    rate?: string;
    payment_reason?: string;
    amount?: string;
  };
  payment_reporting?: {
    conditions?: "TP01" | "TP02" | "TP03";
    method?:
      | "MP01"
      | "MP02"
      | "MP03"
      | "MP04"
      | "MP05"
      | "MP06"
      | "MP07"
      | "MP08"
      | "MP09"
      | "MP10"
      | "MP11"
      | "MP12"
      | "MP13"
      | "MP14"
      | "MP15"
      | "MP16"
      | "MP17"
      | "MP18"
      | "MP19"
      | "MP20"
      | "MP21"
      | "MP22";
  };
  /**
   * ID of the quote this invoice was created from, if any.
   *
   */
  quote_id?: string;
  /**
   * Nature of the invoice.
   *
   * - `standard`: the invoice covers the whole amount of the items it lists.
   * - `deposit`: the invoice covers an advance payment on a larger order.
   * - `partial`: progress invoice (facture de situation). The invoice covers a
   *   share of the work described by its items, so `total_amount` is a fraction
   *   of the value of those items.
   * - `balance`: the invoice covers the remainder of an order, net of a deposit.
   *
   * Only `standard` invoices are guaranteed to have `total_amount` equal to the
   * sum of their line items. For every other type, rely on `total_amount` and
   * `total_amount_cents` for the amount actually invoiced and due. The progress
   * share of a `partial` invoice is not exposed by the API.
   *
   */
  invoice_type: "standard" | "deposit" | "partial" | "balance";
  einvoicing_lifecycle_events?: EinvoicingLifecycleEvents;
};

export type ClientInvoiceCreatePayload = {
  /**
   * The ID of the associated client. The client is validated against the business rules of the invoicing domain.
   * In case of getting a validation error related to a field in the customer, you will need to issue a request to
   * update the customer itself and then try to re-create the invoice itself.
   * This is because a client can be used across different domains - client creation performs only minimal
   * validations on the client and then it is up to each domain (for example, invoicing) to apply their own
   * business rules on top of that client. More information can be found in [the docs for creating a client](/api-reference/business-api/invoicing/clients/create-a-client).
   *
   */
  client_id: string;
  /**
   * Optional ID of a previously uploaded file to attach to this invoice. The upload must have been created using the [POST /v2/client_invoices/uploads](/api-reference/business-api/invoicing/client-invoices/create-a-client-invoice-upload) endpoint.
   *
   */
  upload_id?: string;
  /**
   * Optional ID of a quote to link to this invoice. The quote must belong to the same organization.
   * If the quote does not exist, a `404` error is returned.
   *
   */
  quote_id?: string;
  issue_date: string;
  /**
   * Start date of the performance period for the invoice. The format should be `YYYY-MM-DD`.
   *
   * The performance period defines the date range during which the job or service is expected to be completed by the client. This field marks the beginning of that period and can be used together with `performance_end_date` to create a flexible date range instead of a single fixed date.
   *
   * **Validation rules:**
   * - Required if `performance_end_date` is provided
   * - Must be less than or equal to `performance_end_date` when both are provided
   *
   * **Fallback behavior:**
   * - If not provided, the system will use the deprecated `performance_date` value as fallback
   * - If provided, this value will override the deprecated `performance_date` field
   *
   */
  performance_start_date?: string;
  /**
   * End date of the performance period for the invoice. The format should be `YYYY-MM-DD`.
   *
   * This field defines the end of the performance date range, allowing clients to complete the job or service anytime between `performance_start_date` and `performance_end_date`. When used together with `performance_start_date`, it creates a flexible time window rather than requiring completion on a specific date.
   *
   * **Validation rules:**
   * - Optional field
   * - When provided, `performance_start_date` becomes required
   * - Must be greater than or equal to `performance_start_date`
   *
   */
  performance_end_date?: string;
  /**
   * Payment deadline that is added by the initiator. The format should be `YYYY-MM-DD`
   */
  due_date: string;
  /**
   * Invoice's status. If not filled, `unpaid` will be automatically propertyd to the invoice.
   */
  status?: "draft" | "unpaid";
  /**
   * Invoice's number. Must be unique within the organization and is:
   * - **required** if automatic numbering is disabled for the authenticated organization;
   * - **optional** if automatic numbering is enabled for the authenticated organization (default setting).
   *   However, if provided, it will be used as the invoice's number.
   */
  number?: string;
  /**
   * Purchase order data added by the invoice’s initiator.
   */
  purchase_order?: string;
  /**
   * Additional notes added by the invoice’s initiator.
   */
  terms_and_conditions?: string;
  header?: string;
  footer?: string;
  /**
   * Currency for the total amount of the invoice. Trigram following ISO 4217.
   */
  currency:
    | "EUR"
    | "AED"
    | "AUD"
    | "BGN"
    | "CAD"
    | "CHF"
    | "CNY"
    | "CZK"
    | "DKK"
    | "GBP"
    | "GHS"
    | "HKD"
    | "HUF"
    | "ILS"
    | "MXN"
    | "NOK"
    | "NZD"
    | "PEN"
    | "PLN"
    | "RON"
    | "RSD"
    | "SAR"
    | "SEK"
    | "SGD"
    | "TRY"
    | "USD"
    | "ZAR"
    | "ZMW";
  /**
   * Payment method details for the invoice.
   */
  payment_methods: {
    /**
     * Beneficiary’s International Bank Account Number (IBAN). The format must follow ISO 13616, and should be a valid IBAN (must start with two letters, followed by 25 digits). The IBAN must be associated to a Qonto account.
     */
    iban: string;
  };
  settings?: InvoiceSettingsOverride;
  items: DocumentItemPayload[];
  /**
   * - For Italian organizations only
   * - Non-Italian organizations should not include this property in the request.
   * - Italian organizations must have e-invoicing activated to use this endpoint, no matter the value of the flag.
   * - By default for an Italian organization that has e-invoicing activated on the Qonto app, if this field is not filled, this property is set to true and the invoice is automatically sent to Italian exchange system (Sistema di Interscambio, or SdI) as an XML e-invoice. If set to `false`, the invoice will not be sent to SdI.
   * - Use the `GET` v2/client_invoices to retrieve its e-invoicing status under the property `einvoicing_status`.
   */
  report_einvoicing?: boolean;
  /**
   * - For Italian organizations only
   * - Non-Italian organizations should not include this property in the request.
   * - Object which relates to payment methods and conditions of the invoice.
   */
  payment_reporting?: {
    /**
     * Payment conditions on the invoice.
     */
    conditions: "TP01" | "TP02" | "TP03";
    /**
     * Payment method of the invoice.
     */
    method:
      | "MP01"
      | "MP02"
      | "MP03"
      | "MP04"
      | "MP05"
      | "MP06"
      | "MP07"
      | "MP08"
      | "MP09"
      | "MP10"
      | "MP11"
      | "MP12"
      | "MP13"
      | "MP14"
      | "MP15"
      | "MP16"
      | "MP17"
      | "MP18"
      | "MP19"
      | "MP20"
      | "MP21"
      | "MP22";
  };
  /**
   * - For Italian organizations only
   * - Non-Italian organizations should not include this property in the request.
   * - Object which relates to pension contributions added to the total amount to pay, applicable in some cases.
   * - This amount is a percentage added to the total amount of the invoice pre-taxes.
   */
  welfare_fund?: {
    /**
     * Welfare fund type.
     */
    type:
      | "TC01"
      | "TC02"
      | "TC03"
      | "TC04"
      | "TC05"
      | "TC06"
      | "TC07"
      | "TC08"
      | "TC09"
      | "TC10"
      | "TC11"
      | "TC12"
      | "TC13"
      | "TC14"
      | "TC15"
      | "TC16"
      | "TC17"
      | "TC18"
      | "TC19"
      | "TC20"
      | "TC21"
      | "TC22";
    /**
     * Welfare fund rate applicable for the invoice. Written in decimals, separated by a period “.” For example, for a rate of 1%, input is 0.01, and for a rate of 10%, input is 0.1
     */
    rate: string;
  };
  /**
   * - Only for Italian organizations and Spanish freelancers
   * - Other organizations should not include this property in the request.
   * - Object which relates to an amount of tax paid by the client, rather than the supplier, for specific cases.
   * - This amount is a percentage deducted from the total amount of the invoice after VAT application.
   * - ES freelancers need to only fill the withholding_tax `rate` field with their IRPF.
   */
  withholding_tax?: {
    /**
     * Reason the withholding tax.
     */
    reason: "RF01" | "RF02" | "RF03" | "RF04" | "RF05" | "RF06";
    /**
     * Withholding tax rate applicable for the invoice. Written in decimals, separated by a period “.” For example, for a rate of 1%, input is 0.01 and for a rate of 10%, input is 0.1
     */
    rate: string;
    /**
     * Payment reason the withholding tax.
     */
    payment_reason: string;
  };
  /**
   * - For Italian organizations only
   * - Non-Italian organizations should not include this property in the request.
   * - Represents an amount (2.00 EUR) applicable on invoices where VAT is excluded and the invoice has a value exceeding 77.47 EUR.
   */
  stamp_duty_amount?: string;
  /**
   * Global discount applied to the entire invoice.
   * This discount is applied to the sum of all items (after item-level discounts, if any).
   */
  discount?: {
    /**
     * Type of the discount. `percentage` for a rate-based discount or `absolute` for a fixed amount discount.
     */
    type?: "percentage" | "absolute";
    /**
     * Rate or absolute amount that will be discounted from the invoice total.
     * - For `percentage` type: Value between 0.0001 (0.01%) and 1 (100%), with at most 4 decimals. For example, for a 20% discount, use `0.2` or `0.20`.
     * - For `absolute` type: Fixed amount to be deducted, with at most 2 decimals. Decimals should be separated by a period "."
     */
    value?: string;
  };
};

