/**
 * Represents a file upload that can be attached to client invoices or quotes.
 */
export type ClientInvoiceUpload = {
  /**
   * Unique identifier for the upload. Use this ID when creating or updating client invoices or quotes.
   */
  id: string;
  /**
   * ID of the organization that owns this upload
   */
  organization_id: string;
  /**
   * Original filename of the uploaded file
   */
  filename: string;
  /**
   * MIME type of the file
   */
  content_type: "application/pdf" | "image/jpeg" | "image/png";
  /**
   * Size of the file in bytes
   */
  file_size: number;
  /**
   * URL to access/download the uploaded file
   */
  url: string;
  /**
   * Timestamp when the upload was created
   */
  created_at: string;
  /**
   * Timestamp when the upload was last updated
   */
  updated_at: string;
};

/**
 * Metadata for paginated client responses.
 *
 * Note: this endpoint returns the previous-page field as `previous_page`
 * (rather than `prev_page`, used elsewhere in the Business API) for backward
 * compatibility with the long-standing clients API. `next_page` and
 * `previous_page` are always present and are `null` on the last/first page.
 *
 */
export type ClientsPagination = {
  /**
   * The current page number
   */
  current_page: number;
  /**
   * The next page number (null if on last page)
   */
  next_page: number | null;
  /**
   * The previous page number (null if on first page)
   */
  previous_page: number | null;
  /**
   * Total number of pages
   */
  total_pages: number;
  /**
   * Total number of items across all pages
   */
  total_count: number;
  /**
   * Number of items per page
   */
  per_page: number;
};

