export type ReminderUpdatePayload = {
  /**
   * The email addresses the reminders are sent to.
   */
  send_to: string[];
  /**
   * Whether a copy of each reminder is also sent to your organization's contact email.
   */
  copy_to_self?: boolean;
  /**
   * The complete reminder schedule. Replaces the existing schedule entirely — see the warning above.
   */
  rules: {
    /**
     * When the reminder is sent, relative to the invoice due date.
     */
    operator: "on" | "before" | "after";
    /**
     * How many days before or after the due date the reminder is sent. Required when `operator` is `before` or `after`. Ignored when `operator` is `on`.
     */
    offset_days?: number;
    /**
     * The subject of the reminder email.
     */
    email_title: string;
    /**
     * The body of the reminder email.
     */
    email_body?: string;
  }[];
};

