export type SepaRecurringTransfer = {
  id: string;
  /**
   * ID of the membership that initiated the transfer
   */
  initiator_id: string;
  /**
   * ID of the bank account to debit from
   */
  bank_account_id: string;
  status?: string;
  amount: number;
  amount_cents: number;
  amount_currency: "EUR";
  beneficiary_id: string;
  reference: string;
  note: string;
  first_execution_date: string;
  last_execution_date: string;
  next_execution_date: string;
  frequency: "weekly" | "monthly" | "quarterly" | "half_yearly" | "yearly";
  created_at: string;
  updated_at: string;
};

export type SepaTransfer = {
  id: string;
  /**
   * ID of the membership that initiated the transfer
   */
  initiator_id: string;
  /**
   * ID of the bank account to debit from
   */
  bank_account_id: string;
  amount: number;
  amount_cents: number;
  amount_currency: "EUR";
  /**
   * Can contain the following values:
   * * `pending`: SEPA transfer is created and has not been processed yet. If transfer is not processed within next minute, it means either execution date may not been reached yet or we are running some compliance checks on this transfer.
   * * `processing`: SEPA transfer processing means account balance is debited and a transaction has been created. Processing status can last up to multiple hours until transfer is sent in the network to the beneficiary.
   * * `canceled`: When the SEPA transfer is canceled by a user in the interface. This is a permanent status.
   * * `declined`: When the SEPA transfer is declined by the screening service, fraud service or, once sent on the network, for many various reasons which are listed in [those guidelines](https://www.europeanpaymentscouncil.eu/sites/default/files/kb/file/2023-11/EPC135-18%20v5.0%20Guidance%20on%20Reason%20Codes%20for%20SCT%20R-transactions.pdf). This is a permanent status.
   * * `settled`: When the SEPA transfer is sent to the network, transfer is settled. This is a permanent status.
   */
  status: "pending" | "processing" | "canceled" | "declined" | "settled";
  beneficiary_id: string;
  reference: string;
  note: string | null;
  /**
   * Populated only when transfer status is declined. Possible values: `beneficiary_bic_invalid`, `beneficiary_iban_invalid`, `beneficiary_status`, `beneficiary_network_rules_error`, `organisation_compliance_reasons`, `debit_account_insufficient_funds`, `qonto_processing_failed`.
   */
  declined_reason:
    | "beneficiary_bic_invalid"
    | "beneficiary_iban_invalid"
    | "beneficiary_status"
    | "beneficiary_network_rules_error"
    | "organisation_compliance_reasons"
    | "debit_account_insufficient_funds"
    | "qonto_processing_failed"
    | null;
  /**
   * YYYY-MM-DD, indicates when the external transfer was scheduled to be sent by Qonto.
   */
  scheduled_date: string;
  /**
   * UTC, the time at which the external transfer was first recorded.
   */
  created_at: string;
  /**
   * UTC, the time at which the external transfer was last updated.
   */
  updated_at: string;
  /**
   * UTC, when the external transfer has been started to be processed by Qonto.
   */
  processed_at: string | null;
  /**
   * UTC, when the external transfer is in its final state, either settled, declined, or canceled.
   */
  completed_at: string | null;
  /**
   * The ID of the transaction associated with the transfer.
   */
  transaction_id: string | null;
  /**
   * The ID of the recurring transfer associated with the transfer.
   */
  recurring_transfer_id: string | null;
};

