  /**
   * List transactions
   *
   * Retrieves the list of transactions for the bank account identified by the `bank_account_id` / `iban` query parameter.
   *
   * You can filter (ex: only retrieve the latest transactions) and sort this list by using [query parameters](#parameter-bank-account-id) 👇
   *
   * <Info>
   *   All transactions visible in Qonto's UI can be retrieved, as of API V2.
   * </Info>
   *
   */
  async listTransactions(
    input: {
      /**
       * `id` of the bank account for which transactions will be retrieved. Use [/v2/organization](/api-reference/business-api/accounts-organizations/organizations/retrieve-the-authenticated-organization-and-list-bank-accounts) to get this parameter. If both `bank_account_id` and `iban` are specified, `bank_account_id` takes precedence.
       */
      bank_account_id?: string;
      /**
       * IBAN of the bank account for which transactions will be retrieved. Use [/v2/organization](/api-reference/business-api/accounts-organizations/organizations/retrieve-the-authenticated-organization-and-list-bank-accounts) to get this parameter. If both `bank_account_id` and `iban` are specified, `bank_account_id` takes precedence.
       */
      iban?: string;
      /**
       * Use this query parameter to embed the associated resources (labels, attachments and/or VAT details) of the transactions in the JSON response.
       */
      "includes[]"?: ("vat_details" | "labels" | "attachments")[];
      /**
       * Transactions can be filtered by their `status` property. Possible values: - `pending`: a transaction that is processing and has impacted the bank account's `auth_balance` but not its `balance`; - `declined`: a transaction that has been declined; - `completed`: a transaction that is completed, and has impacted the bank account's `balance`; - `reversed`: a transaction that has been reversed after being completed. When not specified, only `completed` transactions will be returned.
       */
      "status[]"?: ("pending" | "declined" | "completed" | "reversed")[];
      /**
       * Transactions can be filtered by their `updated_at` property. This filter can be used in combination with the `updated_at_to` query parameter to get transactions updated within a specific timeframe. Please use a valid date time format (**ISO 8601** for instance).
       */
      updated_at_from?: string;
      /**
       * Transactions can be filtered by their `updated_at` property. This filter can be used in combination with the `updated_at_from` query parameter to get transactions updated within a specific timeframe. Please use a valid date time format (**ISO 8601** for instance).
       */
      updated_at_to?: string;
      /**
       * Transactions can be filtered by their `created_at` property. This filter can be used in combination with the `created_at_to` query parameter to get transactions created within a specific timeframe. Please use a valid date time format (**ISO 8601** for instance).
       */
      created_at_from?: string;
      /**
       * Transactions can be filtered by their `created_at` property. This filter can be used in combination with the `created_at_from` query parameter to get transactions created within a specific timeframe. Please use a valid date time format (**ISO 8601** for instance).
       */
      created_at_to?: string;
      /**
       * Transactions can be filtered by their `emitted_at` property. This filter can be used in combination with the `emitted_at_to` query parameter to get transactions emitted within a specific timeframe. Please use a valid date time format (**ISO 8601** for instance).
       */
      emitted_at_from?: string;
      /**
       * Transactions can be filtered by their `emitted_at` property. This filter can be used in combination with the `emitted_at_from` query parameter to get transactions emitted within a specific timeframe. Please use a valid date time format (**ISO 8601** for instance).
       */
      emitted_at_to?: string;
      /**
       * Transactions can be filtered by their `settled_at` property. This filter can be used in combination with the `settled_at_to` query parameter to get transactions settled within a specific timeframe. Please use a valid date time format (**ISO 8601** for instance).
       */
      settled_at_from?: string;
      /**
       * Transactions can be filtered by their `settled_at` property. This filter can be used in combination with the `settled_at_from` query parameter to get transactions settled within a specific timeframe. Please use a valid date time format (**ISO 8601** for instance).
       */
      settled_at_to?: string;
      /**
       * Transactions can be filtered by their `side` property.
       */
      side?: "credit" | "debit";
      /**
       * Transactions can be filtered by their `operation_type` property.
       */
      "operation_type[]"?: string[];
      /**
       * Transactions can be filtered based on the presence of one or more attachments.
       */
      with_attachments?: boolean;
      /**
       * Sorts transactions, written as `property:order`. - `property`: `settled_at` (default), `created_at`, `updated_at` or `emitted_at`. - `order`: `asc` or `desc` (default). Either part can be left out: - `settled_at` is `settled_at:desc`. - `:asc` is `settled_at:asc`.
       */
      sort_by?: string;
      /**
       * Returned page (cf. [Pagination](/api-reference/business-api/introduction/pagination)). Must be an integer of 1 or more, otherwise the API returns a 422. `page` × `per_page` can't exceed 10,000. Past that, the API returns a 422 too. To reach older transactions, narrow the date filters.
       */
      page?: number;
      /**
       * Number of transactions per page (cf. [Pagination](/api-reference/business-api/introduction/pagination)). Values outside the 1 to 100 range are clamped to it. A value that isn't an integer, such as `50.0`, is treated as 1.
       */
      per_page?: number;
    } = {},
  ): Promise<
    QontoResult<{
      transactions?: Transaction[];
      meta?: Pagination;
    }>
  > {
    return run(this.env, this.ctx.props, "listTransactions", input);
  }

